// Title: Add a JavaScript page-number footer when exporting an Excel worksheet to HTML using Aspose.Cells for .NET (C#)
// Common Searches: C# Aspose.Cells export active worksheet to HTML with custom JavaScript footer | how to insert a pagination script into HTML generated by Aspose.Cells | add fixed footer showing total pages in HTML output from Excel using Aspose.Cells | modify Aspose.Cells HTML output to include page count via memory stream | Aspose.Cells HtmlSaveOptions add JavaScript for page numbering
// Tags: Aspose.Cells HTML export custom footer | C# add JavaScript pagination to exported HTML | modify generated HTML via MemoryStream Aspose.Cells | fixed position footer page count script | export active worksheet only HtmlSaveOptions

using System;
using System.IO;
using System.Text;
using Aspose.Cells;

// The example loads an Excel workbook, configures HtmlSaveOptions to export only the active sheet with UTF‑8 encoding, saves the result to a MemoryStream, injects a fixed‑position footer containing a JavaScript snippet that calculates total pages based on a fixed page height, replaces the closing </body> tag with this footer, and writes the final HTML file.
class Program
{
    static void Main()
    {
        // Load the source Excel workbook
        Workbook workbook = new Workbook("input.xlsx");

        // Configure HTML save options
        HtmlSaveOptions htmlOptions = new HtmlSaveOptions
        {
            // Export only the active worksheet (optional)
            ExportActiveWorksheetOnly = true,
            // Use UTF-8 encoding for the generated HTML
            Encoding = Encoding.UTF8
        };

        // Save the workbook to a memory stream so we can edit the HTML before writing to disk
        using (MemoryStream htmlStream = new MemoryStream())
        {
            workbook.Save(htmlStream, htmlOptions);
            htmlStream.Position = 0;

            // Read the generated HTML into a string
            string htmlContent = new StreamReader(htmlStream).ReadToEnd();

            // Define a footer with a JavaScript snippet that calculates page numbers
            string footerHtml = @"
<div id='footer' style='position:fixed; bottom:0; width:100%; text-align:center; font-size:12px; background:#f0f0f0; padding:5px;'>
    Page <span id='pageNumber'></span>
</div>
<script>
    // Simple pagination script: assumes A4 page height at 96 DPI (~1122px)
    (function () {
        var pageHeight = 1122; // pixels per page
        var totalHeight = document.body.scrollHeight;
        var totalPages = Math.ceil(totalHeight / pageHeight);
        document.getElementById('pageNumber').innerText = totalPages;
    })();
</script>
</body>";

            // Insert the footer just before the closing </body> tag
            htmlContent = htmlContent.Replace("</body>", footerHtml);

            // Write the final HTML to a file
            File.WriteAllText("output.html", htmlContent, Encoding.UTF8);
        }
    }
}
